import type { CheckboxGroupProps } from "./checkbox-group.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "CheckboxGroup";

// Generate child element class names for the component, should match available style slots
export const CheckboxGroupClasses = {
  root: "exp-textura_checkbox-group",
  itemLabel: "exp-textura_checkbox-group-item-label",
  itemLabelText: "exp-textura_checkbox-group-item-label-text",
  itemSubtext: "exp-textura_checkbox-group-item-subtext",
  item: "exp-textura_checkbox-group-item",
  sm: "exp-textura_checkbox-group_sm",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {},
  inverse: {
    itemLabelText: {
      color: theme.color.content.inverse,
    },
    itemLabelDisabled: {
      color: theme.inputSelect.checkbox.off.inverse.color.content.disabled,
    },
    itemSubtext: {
      color: theme.color.content.weak,
    },
    itemSubtextDisabled: {
      color: theme.inputSelect.checkbox.off.inverse.color.content.disabled,
    },
  },
});

const generateStyles = (props: CheckboxGroupProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<CheckboxGroupProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[12]),
    color: theme.color.content.default,
    fontFamily: theme.typography.fontFamily.plusJakartaSans,
    fontWeight: theme.typography.fontWeight[400],
    fontSize: theme.typography.fontSize[14],
    letterSpacing: theme.typography.letterSpacing[0],
    lineHeight: theme.typography.lineHeight[20],

    "&[data-disabled]": {
      color: theme.color.content.disabled,
      ...styleSlots?.disabled,
    },

    "&[data-orientation='horizontal']": {
      flexDirection: "row",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.horizontal,
    },

    [`&.${CheckboxGroupClasses.sm}`]: {
      gap: theme.toRem(theme.spacing[8]),
      [`.${CheckboxGroupClasses.itemLabel}`]: {
        ...styleSlots?.itemLabelSm,
      },
      [`.${CheckboxGroupClasses.itemLabelText}`]: {
        ...theme.typography.body.sm,
        lineHeight: theme.typography.lineHeight[16],
        ...styleSlots?.itemLabelTextSm,
      },
      [`.${CheckboxGroupClasses.itemSubtext}`]: {
        ...theme.typography.body.sm,
        lineHeight: theme.typography.lineHeight[16],
        ...styleSlots?.itemSubtextSm,
      },
      ...styleSlots?.sm,
    },

    [`.${CheckboxGroupClasses.item}`]: {
      display: "flex",
      flexDirection: "row",
      alignItems: "flex-start",
      ...styleSlots?.item,
    },

    [`.${CheckboxGroupClasses.itemLabel}`]: {
      paddingInlineStart: theme.toRem(theme.spacing[8]),
      display: "flex",
      flexDirection: "column",
      alignItems: "flex-start",
      [`&[data-disabled]`]: {
        ...styleSlots?.itemLabelDisabled,
        [`.${CheckboxGroupClasses.itemLabelText}`]: {
          color: theme.inputSelect.checkbox.off.default.color.content.disabled,
          ...styleSlots?.itemLabelTextDisabled,
        },
        [`.${CheckboxGroupClasses.itemSubtext}`]: {
          color: theme.inputSelect.checkbox.off.default.color.content.disabled,
          ...styleSlots?.itemSubtextDisabled,
        },
      },
      ...styleSlots?.itemLabel,
    },

    [`.${CheckboxGroupClasses.itemLabelText}`]: {
      ...theme.typography.body.md,
      lineHeight: theme.typography.lineHeight[16],
      color: theme.color.content.default,
      ...styleSlots?.itemLabelText,
    },

    [`.${CheckboxGroupClasses.itemSubtext}`]: {
      ...theme.typography.body.sm,
      lineHeight: theme.typography.lineHeight[16],
      color: theme.color.content.weak,
      ...styleSlots?.itemSubtext,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledCheckboxGroup = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<CheckboxGroupProps>((props) => generateStyles(props));
